def markup(tooltip):
    """'Bold (Ctrl+B)' -> '<b>Bold (Ctrl+B)</b>\\n\\nMake your text bold.' (Pango markup)."""
    from gi.repository import GLib
    title = " ".join((tooltip or "").split())
    base = title.split(" (")[0]
    desc = TIPS.get(base)
    if not desc:
        return None
    return "<b>%s</b>\n\n%s" % (GLib.markup_escape_text(title), GLib.markup_escape_text(desc))
